    max-width: 32ch;
  }

  .hero__lede {
    font-size: 0.95rem;
140→    line-height: 1.5;
    color: var(--blume-muted-foreground);
    margin: 0 0 1.1rem;
    max-width: 42ch;
  }

  .hero__note {
    margin: 0.85rem 0 0;
    font-family: var(--blume-font-mono);
    font-size: 0.7rem;
150→    letter-spacing: 0.02em;
    color: var(--blume-muted-foreground);
  }

  .hero__note a {
    color: var(--blume-accent);
    text-decoration: none;
  }

  .hero__note a:hover {
160→    text-decoration: underline;
  }

  .hero__lede code,
  .hero__note code {
    font-family: var(--blume-font-mono);
    font-size: 0.85em;
  }

  .hero__ctas {
170→    display: flex;
    flex-direction: column;
